import{_ as t,o as i,c as s,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-11-12 :: Ceph Testing Meeting","description":"","frontmatter":{"title":"2019-11-12 :: Ceph Testing Meeting","date":"2019-11-12T00:00:00.000Z","updated":"2019-11-18T00:00:00.000Z","tags":["Ceph","分布式存储","软件开发","测试","OpenStack","Kubernetes","Docker"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-12_-_-_Ceph_Testing_Meeting.md","filePath":"posts/2019/2019-11-12_-_-_Ceph_Testing_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-11-12_-_-_Ceph_Testing_Meeting.md"};function o(a,e,r,p,g,_){return i(),s("div",null,[...e[0]||(e[0]=[n('<p>categories:</p><ul><li>&quot;视频总结&quot; subtitle: 2019-11-12_-_-_Ceph_Testing_Meeting</li></ul><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Kira, Yuri, Nathan, Sage, Jason, 安德鲁，以及其他未具名成员</p><p><strong>会议主题</strong>： Ceph项目进展、问题讨论和后续行动计划</p><p><strong>关键细节</strong>：</p><ul><li><strong>Ceph Mimic版本</strong>： Sage发布了一个针对Mimic的PR，旨在解决升级和客户端测试失败的问题。Nathan已开始测试该PR，并计划将其合并到Mimic的候选版本中。会议决定合并该PR，并运行测试以验证其效果。</li><li><strong>Ceph Luminous版本</strong>： 目前没有针对Luminous的PR，主要关注Nautilus版本。会议决定将Luminous版本作为最后一个LTS版本，并给予更多时间来完善。</li><li><strong>Ceph Nautilus版本</strong>： Sage提到一个潜在回归，其中BlueStore在某些情况下会导致数据损坏。如果有人提交修复该问题的PR，则将立即进行热修复。</li><li><strong>Ceph Octopus版本</strong>： Timothy九有一个关于Oculus的PR。会议讨论了测试和部署Oculus的进展。</li><li><strong>Ceph测试</strong>： Sage正在编写新的测试用例，用于测试Ceph集群管理器。讨论了在OpenStack上进行测试的可能性。</li><li><strong>Ceph任务</strong>： Sage正在重构Ceph任务，以提高其效率和可靠性。讨论了使用容器进行任务升级的可能性。</li><li><strong>Ceph PR管理</strong>： 讨论了一些旧的PR，并决定关闭一些不再需要的PR。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>合并Sage的Mimic PR，并运行测试以验证其效果。</li><li>继续关注Luminous版本，并给予更多时间来完善。</li><li>如果有人提交修复BlueStore回归问题的PR，则立即进行热修复。</li><li>继续推进Oculus的测试和部署。</li><li>继续重构Ceph任务，并提高其效率和可靠性。</li><li>关闭一些不再需要的PR。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Nathan将合并Sage的Mimic PR，并运行测试。</li><li>Sage将继续推进Oculus的测试和部署。</li><li>Sage将继续重构Ceph任务，并提高其效率和可靠性。</li><li>会议参与者将继续关注Ceph项目的进展，并积极参与。</li></ul>',12)])])}const c=t(l,[["render",o]]);export{h as __pageData,c as default};
